struct fat_attr_data {
    __u8 attributes;
    __le16 creation_date;
    // ... size and cluster fields
};

int fd; // Existing file descriptor
struct fat_attr_data attrs;
int status;

// Retrieve FAT attributes for the file
status = ioctl(fd, FAT_IOCTL_GET_ATTRIBUTES, &attrs);

// Set Volume Label (requires specific command and data)
const char* new_label = "MY_VOL_ID";
ioctl(fd, FAT_IOCTL_SET_VOLUME_ID, (void*)new_label);

// Read directory entry data
struct vfat_dir_entry dir_data;
ioctl(fd, VFAT_IOCTL_READDIR_BOTH, &dir_data);
